-- Form thuyền viên mới: tên tiếng Trung, nguyên quán, size bảo hộ, ảnh chân dung 4x6,
-- nhiều tài khoản ngân hàng. Tạo hồ sơ chỉ cần họ tên nên ngày sinh không còn bắt buộc.
ALTER TABLE "seafarer"
  ADD COLUMN "full_name_zh" varchar(150),
  ADD COLUMN "place_of_origin" varchar(255),
  ADD COLUMN "ppe_size" varchar(10),
  ADD COLUMN "photo_path" varchar(500),
  ADD COLUMN "photo_mime" varchar(50),
  ADD COLUMN "photo_updated_at" TIMESTAMP WITHOUT TIME ZONE,
  ALTER COLUMN "date_of_birth" DROP NOT NULL;

CREATE TABLE "seafarer_bank_account" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY,
  "seafarer_id" INTEGER NOT NULL REFERENCES "seafarer" ("id") ON DELETE CASCADE,
  "bank_name" varchar(100),
  "account_number" varchar(30),
  "account_holder" varchar(150),
  "sort_order" SMALLINT DEFAULT 0 NOT NULL,
  "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL
);

CREATE TRIGGER "seafarer_bank_account_updated_at" BEFORE UPDATE ON "seafarer_bank_account" FOR EACH ROW EXECUTE FUNCTION touch_updated_at();
CREATE INDEX "seafarer_bank_account_seafarer_id" ON "seafarer_bank_account" ("seafarer_id", "sort_order");

-- Tài khoản đang ghi trên hồ sơ thành tài khoản đầu tiên. Cột bank_* trên seafarer vẫn giữ,
-- luôn bằng tài khoản đầu tiên, để biểu mẫu Excel đang đọc chúng không phải đổi.
INSERT INTO "seafarer_bank_account" ("seafarer_id", "bank_name", "account_number", "account_holder", "sort_order")
SELECT "id", "bank_name", "bank_account_number", "bank_account_holder", 0
FROM "seafarer"
WHERE COALESCE("bank_name", "bank_account_number", "bank_account_holder") IS NOT NULL;
